    /**
     * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
     * @param desiredCapacity the capacity desired by the user.
     * @return the capacity which should be used for a hashtable.
     */
    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity < 2) return 2;
        int candidate = desiredCapacity;
        // Ensure candidate is odd when > 2
        if (candidate > 2 && candidate % 2 == 0) candidate++;
        while (true) {
            if (isPrime(candidate)) {
                // For capacities >= 1000 we enforce the 11% bound
                if (desiredCapacity >= 1000) {
                    if (candidate <= desiredCapacity + (int)(desiredCapacity * 0.11)) {
                        return candidate;
                    }
                } else {
                    return candidate;
                }
            }
            candidate += 2; // skip even numbers
        }
    }

