private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // unlink from previous node
    if (node.prev != null) {
        node.prev.next = node.next;
    } else { // node is head
        head = node.next;
    }

    // unlink from next node
    if (node.next != null) {
        node.next.prev = node.prev;
    } else { // node is tail
        tail = node.prev;
    }

    // detach node
    node.prev = null;
    node.next = null;
    node.value = null;

    size--;
    return true;
}

